15	/// Maps token denoms to their origin path, which is used to determine if a token
16	/// should be unwrapped when sent back to its origin chain.
17	pub const TOKEN_ORIGIN: Map<String, Uint256> = Map::new("token_origin");
18	
19	/// Tracks the balance of tokens escrowed for each (channel, path, denom) combination.
20	/// This is used to ensure we don't unescrow more tokens than were originally escrowed.
21	/// The path is used to track tokens across multiple hops, matching the Solidity implementation.
22	pub const CHANNEL_BALANCE: Map<(u32, Vec<u8>, String), Uint256> = Map::new("channel_balance_v2");
23	
24	/// Temporarily stores the packet being executed to prevent reentrancy attacks.
25	/// This is cleared after execution is complete.
26	pub const EXECUTING_PACKET: Item<Packet> = Item::new("executing_packet");
27	
28	/// Flag to indicate that the currently executing packet is a batch.
29	/// This is used to determine how to handle acknowledgements in the reply handler.
30	pub const EXECUTING_PACKET_IS_BATCH: Item<usize> = Item::new("executing_packet_is_batch");
31	
32	/// Temporarily stores the acknowledgement from packet execution.
33	/// This is used to retrieve the acknowledgement in the reply handler.
34	pub const EXECUTION_ACK: Item<Bytes> = Item::new("execution_ack");
35	
36	/// Stores acknowledgements from batch instruction executions.
37	/// Each instruction in a batch generates its own acknowledgement, which is stored here
38	/// until all instructions have been executed, then combined into a single batch acknowledgement.
39	pub const BATCH_EXECUTION_ACKS: Item<Vec<Bytes>> = Item::new("batch_execution_acks");
40	
41	/// Maps wrapped token denoms to their original token bytes representation.
42	/// This is used to determine the original token when unwrapping.
43	pub const HASH_TO_FOREIGN_TOKEN: Map<String, Bytes> = Map::new("hash_to_foreign_token");
44	
45	/// Maps packet hash to parent packet for forwarded packets.
46	/// This is used to handle acknowledgements and timeouts for packets that are forwarded
47	/// through multiple chains. When a forwarded packet is acknowledged or times out,
48	/// we need to find the original packet that initiated the forward to properly
49	/// propagate the acknowledgement or timeout back to the source.
50	pub const IN_FLIGHT_PACKET: Map<Vec<u8>, Packet> = Map::new("in_flight_packet");
51	
52	pub const MARKET_MAKER: Item<Bytes> = Item::new("market_maker");
