24	        // Test with matching sender
25	        let multiplex = Multiplex {
26	            sender: sender.as_bytes().to_vec().into(),
27	            eureka: false,
28	            contract_address: Addr::unchecked("contract").as_bytes().to_vec().into(),
29	            contract_calldata: vec![].into(),
