1933	pub fn dequeue_channel_from_path(path: U256) -> (U256, Option<ChannelId>) {
1934	    if path == U256::ZERO {
1935	        (U256::ZERO, None)
1936	    } else {
1937	        (
1938	            path >> 32,
1939	            // expect/Some is intentional, such that any bugs are loud and not silently accepted
1940	            Some(
1941	                ChannelId::from_raw(
1942	                    u32::try_from(path & U256::from(u32::MAX)).expect("impossible"),
1943	                )
1944	                .expect("value is > 0 as path is > 0; qed;"),
1945	            ),
1946	        )
1947	    }
1948	}
