1950	/// Extract the last channel from a path and return the base path without it
1951	pub fn pop_channel_from_path(path: U256) -> (U256, Option<ChannelId>) {
1952	    if path == U256::ZERO {
1953	        return (U256::ZERO, None);
1954	    }
1955	    // Find the highest non-zero 32-bit chunk (leftmost)
1956	    let highest_index = (256 - path.leading_zeros() - 1) / 32;
1957	    // Extract the channel ID from the highest non-zero slot
1958	    let channel_id = get_channel_from_path(path, highest_index);
1959	    // Clear that slot in the path
1960	    let mask = !(U256::from(u32::MAX) << (highest_index * 32));
1961	    let base_path = path & mask;
1962	    (base_path, channel_id)
1963	}
