1965	pub fn update_channel_path(path: U256, next_channel_id: ChannelId) -> Result<U256, ContractError> {
1966	    if path == U256::ZERO {
1967	        Ok(U256::from(next_channel_id.raw()))
1968	    } else {
1969	        let next_hop_index = (256 - path.leading_zeros()) / 32 + 1;
1970	        if next_hop_index > 7 {
1971	            return Err(ContractError::ChannelPathIsFull {
1972	                path,
1973	                next_hop_index,
1974	            });
1975	        }
1976	        Ok(make_path_from_channel(next_channel_id, next_hop_index) | path)
1977	    }
1978	}
